begin;
select set_config('request.jwt.claim.sub',(select user_id::text from public.app_members where active and role='admin' limit 1),true);
select set_config('request.jwt.claims',jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now()))))::text,true);
insert into public.products(id,sku,name,category,mode,owner_name,price,qty) values ('qa-purchase-a','QA-PUR-A','A','Perfumes','proprio','QA',100,5),('qa-purchase-b','QA-PUR-B','B','Perfumes','proprio','QA',100,5);
set local role authenticated;
do $$ declare sale text; rev jsonb; original_schedule jsonb; req uuid:=gen_random_uuid(); cancel_id uuid:=gen_random_uuid(); begin
 perform public.register_vip_sale_cart('qa-purchase', '[{"product_id":"qa-purchase-a","qty":1},{"product_id":"qa-purchase-b","qty":1}]','{"down_payment":50,"down_payment_method":"Pix","installments":[{"amount":150,"due_date":"2027-01-01"}]}','Cliente antigo','');
 select min(id),jsonb_object_agg(id,revision) into sale,rev from public.sales where cart_id='qa-purchase';
 select jsonb_agg(to_jsonb(r) order by id) into original_schedule from public.receivable_installments r where cart_id='qa-purchase';
 perform public.finance_purchase_edit(req,sale,rev,'customer','Cliente corrigido','86999999999','Identificar cliente correto');
 assert (select bool_and(customer_name='Cliente corrigido') from public.sales where cart_id='qa-purchase'),'Identity not propagated';
 assert original_schedule=(select jsonb_agg(to_jsonb(r) order by id) from public.receivable_installments r where cart_id='qa-purchase'),'Schedule changed';
 assert (select count(*)=0 from public.customers where name='Cliente corrigido'),'Legacy identity must not auto-merge customers';
 perform public.finance_purchase_edit(req,sale,rev,'customer','Cliente corrigido','86999999999','Identificar cliente correto');
 begin perform public.finance_purchase_edit(gen_random_uuid(),sale,rev,'cancel_purchase','','','Cancelar compra teste');raise exception 'Stale revision accepted';exception when sqlstate '22023' then null;end;
 select jsonb_object_agg(id,revision) into rev from public.sales where cart_id='qa-purchase';
 perform public.finance_purchase_edit(cancel_id,sale,rev,'cancel_purchase','','','Cancelar compra teste');
 perform public.finance_purchase_edit(cancel_id,sale,rev,'cancel_purchase','','','Cancelar compra teste');
 assert (select bool_and(qty=5) from public.products where id in ('qa-purchase-a','qa-purchase-b')),'Restock missing or doubled';
 assert (select sum(amount-paid_amount)=0 from public.receivable_installments where cart_id='qa-purchase'),'Debt remains';
 assert (select sum(amount)=50 from public.receivable_payments where receivable_id in(select id from public.receivable_installments where cart_id='qa-purchase')),'Receipts lost';
 assert (select sum(amount)=-50 from public.finance_pending where sale_id in(select id from public.sales where cart_id='qa-purchase') and status='Pendente'),'Refund mismatch';
 assert (select count(*)=2 from public.finance_events where id in('purchase:'||req,'purchase:'||cancel_id)),'Missing audit';
end $$;
reset role;
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
do $$ begin begin perform public.finance_purchase_edit(gen_random_uuid(),'x','{}','customer','Cliente','','Teste sem senha');raise exception 'Missing fresh password accepted';exception when insufficient_privilege then null;end;end $$;
reset role;
set local role anon;
do $$ begin begin perform public.finance_purchase_edit(gen_random_uuid(),'x','{}','customer','Cliente','','Teste anônimo');raise exception 'Anon allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
rollback;
select 'PASS: customer identity, preserved installments/payments, atomic purchase cancellation, stock, refunds, stale revisions, retries, fresh password and anonymous rejection' as result;
